# Actual application/funding/account identities with independently dated product fits.
if(!exists('fit_binary_glm'))library(creditratingsystem)
rj_fp<-function(x)content_fingerprint(x)$value
rj_vec<-function(rows,key)vapply(rows,function(x)x[[key]],character(1))
rj_num<-function(rows,key)vapply(rows,function(x)as.numeric(x[[key]]),numeric(1))
rj_get<-function(rows,key,value)Filter(function(x)identical(x[[key]],value),rows)
rj_one<-function(rows,key,value){z<-rj_get(rows,key,value);if(length(z)!=1L)stop('Expected one identity');z[[1]]}
rj_resource<-function(name){p<-system.file('extdata',name,package='creditratingsystem');if(!nzchar(p))p<-file.path('creditratingsystem-r/inst/extdata',name);p}
rj_sources<-function(data,applications_path=NULL,releases_path=NULL){
 if(is.null(applications_path))applications_path<-rj_resource('journey_applications.csv');if(is.null(releases_path))releases_path<-rj_resource('journey_releases.csv')
 a<-read_local_dataset(applications_path,data$left_schema);r<-read_local_dataset(releases_path,data$right_schema);control<-data$source_controls
 if(!identical(sort(rj_vec(a$value,'record_id')),sort(unlist(control$record_ids)))||length(a$value)!=control$total_count||sum(rj_num(a$value,'balance'))!=control$total_requested_amount)stop('Application archive control mismatch')
 joined<-join_as_of(a$value,r$value)$value;if(any(vapply(joined,function(x)is.null(x$release_id),logical(1))))stop('Missing historical source evidence')
 audits<-list()
 for(cutoff in sort(unique(rj_vec(joined,'as_of')))){
  left<-rj_get(a$value,'as_of',cutoff);out<-rj_get(joined,'as_of',cutoff);right<-Filter(function(x)x$release_id%in%rj_vec(out,'release_id'),r$value)
  node<-function(identity,kind,rows,source){records<-lapply(rows,function(x)list(record_id=if(source=='release')x$release_id else x$record_id,join_key=x$entity_id,weight=1,amounts=list(amount=if(source=='release')0 else x$balance)));n<-list(node_id=identity,kind=kind,schema_version='1',vintage=cutoff,revision='original',transformation_version='as-of-1',content_hash=rj_fp(rows),observed_at=max(rj_vec(rows,if(source=='release')'observed_at'else'as_of')),available_at=max(rj_vec(rows,if(source=='release')'available_at'else'known_at')),records=records);if(kind=='SOURCE'){n$source_id<-identity;n$semantic_role<-'FEATURE'};n}
  nodes<-list(node('applications','SOURCE',left,'app'),node('releases','SOURCE',right,'release'),node('joined','FEATURE',out,'app'))
  refs<-lapply(nodes,function(n)list(reconciliation_id=paste0('control-',n$node_id),node_id=n$node_id,reference='supplied-through-door-control',expected_record_ids=as.list(rj_vec(n$records,'record_id')),expected_total_weight=length(left),expected_amounts=list(amount=if(n$node_id=='releases')0 else sum(rj_num(left,'balance')))))
  join<-list(join_id='asof',left_node_id='applications',right_node_id='releases',output_node_id='joined',cardinality='one_to_one',join_type='left',weight_contract='LEFT_WEIGHT_ALLOCATION',amount_origin='LEFT',mapping=lapply(out,function(x)list(output_id=x$record_id,left_id=x$record_id,right_id=x$release_id,allocation_weight=1)),excluded_left_ids=list(),unmatched_right_ids=list())
  contract<-list(contract_id='application-source-control',version='1',reference='declared-date-specific-control',amount_fields=list(amount='EUR'),absolute_tolerance=0,relative_tolerance=0,required_node_ids=list('applications','releases','joined'),required_use_ids=list('application'),required_join_ids=list('asof'))
  args<-list(nodes=nodes,edges=list(list(parent_id='applications',child_id='joined'),list(parent_id='releases',child_id='joined')),joins=list(join),reconciliations=refs,uses=list(list(use_id='application',node_id='joined',purpose='FEATURE',as_of=cutoff,known_at=cutoff,source_snapshot_hashes=list(applications=nodes[[1]]$content_hash,releases=nodes[[2]]$content_hash))),contract=contract)
  audits[[length(audits)+1L]]<-list(cutoff=cutoff,inputs=args,result=do.call(validate_source_lineage,args)$value)
 }
 list(rows=joined,audits=audits,archive_hashes=list(applications=a$provenance$source_sha256,releases=r$provenance$source_sha256))
}
rj_fit<-function(product,c,target){
 checked<-function(role){rows<-c[[role]];for(r in rows){if(!(r$feature_observed_at<=r$feature_known_at&&r$feature_known_at<r$application_at&&r$application_at<=r$first_draw_at&&r$first_draw_at<r$outcome_end&&r$outcome_end<=r$outcome_known_at))stop('Prior cohort chronology invalid');observed<-as.integer(!is.null(r$default_at)&&r$first_draw_at<r$default_at&&r$default_at<=r$outcome_end);if(observed!=r$outcome||as.numeric(as.Date(r$outcome_end)-as.Date(r$first_draw_at))!=target$horizon)stop('Prior outcome mismatch')};rows}
 train<-checked('training');cal<-checked('calibration');if(length(intersect(rj_vec(train,'customer_id'),rj_vec(cal,'customer_id'))))stop('Training/calibration overlap');known<-max(rj_vec(train,'outcome_known_at'));if(known>=min(rj_vec(cal,'application_at')))stop('Training not prior')
 model<-fit_binary_glm(matrix(rj_num(train,'driver'),ncol=1),rj_num(train,'outcome'),feature_order='driver',link='logit',fit_intercept=TRUE,target=target,training=list(known_at=known,data_fingerprint=rj_fp(train),split_id=paste0(product,'-prior-training'),data_origin='SYNTHETIC'),model_id=paste0(product,'-application'),model_version='1')$model
 model$application_contract<-list(product_ids=list(product),population_ids=list(paste0(product,'-through-door')),performance_origin='first_draw_at',term_stage='requested',term_features=setNames(list(),character()))
 raw<-as.list(predict_pd(model,matrix(rj_num(cal,'driver'),ncol=1),feature_order='driver',expected_target=target)$value)
 metadata<-list(target=target,calibration=list(start=min(rj_vec(cal,'application_at')),end=max(rj_vec(cal,'outcome_end')),known_at=max(rj_vec(cal,'outcome_known_at')),split_id=paste0(product,'-prior-calibration'),prediction_origin='HOLDOUT'),base_model_version='1',population_definition=paste(product,'funded prior applicants'),outcome_policy='First observed default in30days from first draw',weight_type='frequency',data_origin='SYNTHETIC')
 calibrator<-calibrate_logistic(unlist(raw),rj_num(cal,'outcome'),metadata=metadata)$value
 oracle<-lapply(c(-1,1),function(x){cell<-Filter(function(r)r$driver==x,train);mean(rj_num(cell,'outcome'))});estimates<-as.list(predict_pd(model,matrix(c(-1,1),ncol=1),feature_order='driver',expected_target=target)$value);if(any(abs(unlist(estimates)-unlist(oracle))>1e-8))stop('Fitted cell MLE mismatch')
 list(model=model,calibrator=calibrator,calibration_inputs=list(values=raw,outcomes=as.list(rj_num(cal,'outcome'))),training_rows=train,calibration_rows=cal,independent_cell_mle=oracle,fit_predictions=estimates)
}
rj_payment<-function(t){switch(t$kind,LEVEL_PRINCIPAL=rep(t$principal/t$periods,t$periods),BALLOON=c(rep((t$principal-t$balloon)/t$periods,t$periods-1),(t$principal-t$balloon)/t$periods+t$balloon),OPERATING_RENT={if(t$customer_residual_liability!=0)stop('Undeclared residual liability');rep(t$rent,12)},GRACE=c(rep(t$grace_payment,2),rep(t$post_grace_payment,8)),OVERLAPPING_PLANS=rep(sum(unlist(t$plan_payments)),t$periods),WEEKLY=unlist(t$weekly_dues),stop('Unsupported payment contract'))}
rj_capacity<-function(app,h,t,source){
 key<-app$application_id;D<-app$application_at;prior<-h$source_date;income<-source$income;if(income!=h$monthly_income)stop('Historical income mismatch')
 component_type<-if(is.null(h$income_component_type))'SALARY'else h$income_component_type
 evidence<-list(release_seq=1,evidence_id=paste0('payroll-',key),customer_id=app$customer_id,component_id=paste0('salary-',key),component_type=component_type,observed_from=prior,observed_until=prior,known_at=prior,amount=income,basis='NET',period='month',currency='EUR',evidence_reference=source$release_id)
 policy<-list(policy_id='verified-income',version='1',known_at='2024-01-01',source_priority=list('DOCUMENT','TRANSACTION','DECLARED'),included_component_types=list(component_type),expected_component_ids=list(evidence$component_id),coverage_status='COMPLETE',maximum_age_days=31,allow_stale=FALSE,relative_discrepancy_threshold=.1)
 reconciled<-reconcile_income_evidence(list(),list(evidence),list(),policy,customer_id=app$customer_id,as_of=D,information_cutoff=D,currency='EUR',period='month',basis='NET')$value
 norm<-normalize_income_period(list(list(economic_id=evidence$component_id,amount=income,frequency='month',basis='net',currency='EUR',kind='recurring')),target_period='month',target_basis='net',currency='EUR',payments_per_year=list(month=12,year=1,week=52),variable_income_factor=1)$value
 expense<-estimate_recurring_expenses(list(list(economic_id=paste0('living-',key),category='living',kind='essential',amount=h$monthly_expense,frequency='month',currency='EUR')),target_period='month',currency='EUR',payments_per_year=list(month=12,year=1),household_profile=list(profile_id='living-cost',required_categories=list('living')))$value
 schedule<-rj_payment(t)
 residual<-if(t$kind=='WEEKLY')residual_income(if(income>100)unlist(t$weekly_income)else rep(income/4,4),unlist(t$weekly_expenses),rep(0,4),schedule,period='weekly',currency='EUR')$value else residual_income(rep(income,length(schedule)),rep(h$monthly_expense,length(schedule)),rep(0,length(schedule)),schedule,period='monthly',currency='EUR')$value
 dsti<-debt_service_to_income(schedule,if(t$kind=='WEEKLY'){if(income>100)unlist(t$weekly_income)else rep(income/4,4)}else rep(income,length(schedule)),period=if(t$kind=='WEEKLY')'weekly'else'monthly',currency='EUR')$value
 payment<-if(t$kind=='WEEKLY')sum(head(schedule,4))else schedule[1]
 baseline<-list(currency='EUR',as_of=D,liquid_buffer=0,cltv_scope='not_applicable',incomes=list(list(economic_id=paste0('income-',key),currency='EUR',monthly_amount=income,basis='net')),expenses=list(list(economic_id=paste0('living-',key),currency='EUR',monthly_amount=h$monthly_expense),list(economic_id=paste0('payment-',key),currency='EUR',monthly_amount=payment)),contracts=list(),collateral=list(),thresholds=list(minimum_residual=0,maximum_dsti=1,maximum_cltv=1))
 dt<-as.Date(D);year<-as.integer(format(dt,'%Y'));month<-as.integer(format(dt,'%m'));day<-as.integer(format(dt,'%d'));if(month==12){year<-year+1;month<-1}else month<-month+1;first<-as.Date(sprintf('%04d-%02d-01',year,month));last<-seq(first,by='month',length.out=2)[2]-1;nextdate<-as.character(first+min(day,as.integer(format(last,'%d')))-1)
 scenario<-list(schema_version='1.0',scenario_id='verified-budget-income-shock',periods=list(list(date=nextdate,fx_to_reporting=list(EUR=1),income_factors=setNames(list(.9),paste0('income-',key)),expense_factors=setNames(list(1,1),paste0(c('living-','payment-'),key)),collateral_factors=setNames(list(),character()),rate_shifts=setNames(list(),character()))))
 stress<-stress_affordability(baseline,scenario)$value
 list(dsti=dsti,income_evidence=reconciled,normalized_income=norm,expenses=expense,schedule=as.list(schedule),residual=residual,baseline=baseline,scenario=scenario,stress=stress,status=if(residual$minimum>=0)'AFFORDABLE'else'NOT_AFFORDABLE',projection_scope='One supplied monthly contractual cash payment is an expense; full weekly/grace/balloon schedule is checked separately. No refinancing or rate reset is inferred.')
}
rj_policy<-function(product,target){target$performance_origin<-NULL;list(schema_version='1.1',policy_id=paste0(product,'-credit-policy'),version='1',approval_reference='independently-prespecified-synthetic-capacity-and-risk-policy',known_at='2024-01-01',effective_from='2024-01-01',effective_until='2026-01-01',target=target,default_action='REFER',missing_action='BLOCKED',fields=list('risk.pd'=list(type='number'),'affordability.status'=list(type='category',values=list('AFFORDABLE','NOT_AFFORDABLE','INSUFFICIENT_EVIDENCE'))),rules=list(list(rule_id='capacity',priority=0,action='DECLINE',reason_code='CAPACITY',when=list(list(field='affordability.status',op='eq',value='NOT_AFFORDABLE'))),list(rule_id='eligible-risk',priority=1,action='APPROVE',reason_code='DECLARED_PD',when=list(list(field='risk.pd',op='le',value=.8)))),approval_contract=list(domain='RETAIL_CREDIT',affordability=list(mode='REQUIRED'),required_gates=list()))}
rj_origination<-function(product,case,target,sources){
 live<-rj_vec(case$applications,'customer_id');if(length(intersect(live,c(rj_vec(case$training,'customer_id'),rj_vec(case$calibration,'customer_id')))))stop('Journey/training overlap')
 fitted<-rj_fit(product,case,target);model<-fitted$model;calibrator<-fitted$calibrator;policy<-compile_credit_decision_policy(rj_policy(product,target))$value
 features<-lapply(case$applications,function(app){source<-rj_one(sources$rows,'record_id',app$application_id);list(application_id=app$application_id,feature='driver',value=source$driver,observed_at=source$observed_at,known_at=source$available_at,source_id=source$release_id)})
 snapshots<-build_application_snapshot(case$applications,features,required_features='driver')$value;labels<-build_application_targets(case$applications,case$decisions,case$bookings,case$defaults,case$exits,target$horizon,'2025-02-10')$value
 registry<-register_rating_model_version(NULL,list(model=model,dependencies=list(calibrator=calibrator),configuration=list(product_id=product)),list(model_id=model$model_id,model_version='1',registered_at='2021-01-01'))$value;mh<-registry$entries[[1]]$model_hash;rows<-requests<-list()
 for(i in seq_along(case$applications)){
  app<-case$applications[[i]];snapshot<-snapshots[[i]];historical<-case$decisions[[i]];h<-case$households[[i]];D<-app$application_at;K<-historical$decided_at;key<-app$application_id;source<-rj_one(sources$rows,'record_id',key);subject<-list(subject_id=app$customer_id,subject_type='customer')
  subjects<-build_rating_subjects(list(customer=list(list(subject_id=subject$subject_id,version='1',effective_from=D,effective_to=NULL,known_at=D,attributes=list(product=product)))),list(),D,D)$value
  rs<-c(subject,list(as_of=D,known_at=D,attributes=list(product=list(value=product,observed_at=D,known_at=D),driver=list(value=snapshot$features$driver,observed_at=source$observed_at,known_at=source$available_at))))
  rules<-list(list(rule_id=product,profile_id=paste0(product,'-application'),profile_version='1',priority=1,effective_from='2024-01-01',effective_to=NULL,known_at='2024-01-01',conditions=list(list(field='product',operator='eq',value=product))))
  route<-route_rating_profile(rs,rules,D,D)$value;contract<-list(contract_id=paste0(product,'-support'),version='1',required_features=list('product','driver'),allowed_values=list(product=list(product)),support_bounds=list(driver=list(-1,1)),maximum_age_days=list(driver=31));applicability<-assess_rating_applicability(rs,contract,D,D)$value
  selected<-select_effective_model(registry,list(list(assignment_id=paste0(product,'-champion'),profile_id=route$profile_id,purpose='application',model_id=model$model_id,model_version='1',model_hash=mh,effective_from='2021-01-01',effective_to='2026-01-01',known_at='2021-01-01')),route$profile_id,'application',D,D)$value
  risk<-predict_application_risk(snapshot,model,target,calibrator=calibrator)$value;bureau<-do.call(build_bureau_features,rj_one(case$bureau_inputs,'customer_id',app$customer_id))$value;budget<-rj_capacity(app,h,case$terms,source);dates<-list(as_of=K,known_at=K);policy_risk<-risk;policy_risk$target$performance_origin<-NULL;policy_risk$as_of<-K;policy_risk$known_at<-K;policy_risk$freshness<-'CURRENT'
  inputs<-list(risk=policy_risk,affordability=c(list(status=budget$status),dates),eligibility=c(list(status='ELIGIBLE'),dates),operations=c(list(status='CLEAR'),dates));decision<-do.call(apply_credit_decision_policy,c(list(policy=policy),inputs,dates))$value
  if((decision$action=='APPROVE')!=(historical$status=='approved'))stop('Historical policy decision mismatch')
  request<-list(row_id=key,known_at=D,model_id=model$model_id,model_version='1',model_hash=mh,recipe=list(method='application_risk',version='1.0',parameters=list(target=target)),input=list(snapshot=snapshot));requests[[i]]<-request
  binding<-list(profile_id=route$profile_id,profile_version='1',model_id=model$model_id,model_version='1',model_hash=mh,input_hash=rj_fp(snapshot));components<-list(c(list(component_id=paste0(key,'-pd'),quantity='PD',value=risk$pd),subject,list(variant='application_given_funding',definition=target)))
  assessment<-compose_risk_assessment(paste0(key,'-assessment'),subject,components,binding,D,D,D)$value
  rows[[i]]<-list(application=app,snapshot=snapshot,label=rj_one(labels,'application_id',key),subjects=subjects,route=route,applicability=applicability,selected_model=selected,risk=risk,capacity=budget,bureau=bureau,assessment=assessment,decision=decision,decision_inputs=inputs,policy_explanation=decompose_policy_decision(decision,list(CAPACITY='Negative full-schedule verified income residual',DECLARED_PD='Within predeclared risk threshold'))$value)
 }
 batch<-rate_subject_batch(requests,registry,paste0(product,'-batch'),'2025-02-10')$value;replay<-replay_assessment_history(requests,registry,batch$rows,'2025-02-10')$value
 list(joint_application=do.call(build_customer_household_graph,case$joint_application)$value,fitted=fitted,policy=policy,registry=registry,applications=rows,targets=labels,batch=batch,replay=replay,requests=requests)
}
rj_performing<-function(product,case,origin,cutoff){
 prior<-case$behavioral_training;trpanel<-build_account_month_panel(prior$accounts,prior$statements,prior$events,observation_dates='2017-12-31')$value$accounts
 trlabels<-build_behavioral_targets(trpanel,prior$events,horizon_months=1,target_event='DEFAULT',competing_events='CLOSED',exit_treatment='competing',evaluation_cutoff='2018-02-01',coverage=prior$coverage)$value;target<-list(event='default',horizon=1,time_unit='months',probability_measure='PHYSICAL',conditioning='performing')
 model<-fit_binary_glm(matrix(numeric(),nrow=length(trlabels),ncol=0),rj_num(trlabels,'label'),feature_order=character(),link='logit',fit_intercept=TRUE,target=target,training=list(known_at='2018-02-01',data_fingerprint=rj_fp(prior),split_id=paste0(product,'-behavioral-prior'),data_origin='SYNTHETIC'),model_id=paste0(product,'-behavioral'),model_version='1')$model
 model$behavioral_contract<-list(risk_unit='account',event_policy='first_default',product_ids=list(product),allowed_states=list('ACTIVE'),maximum_source_age_days=0)
 accounts<-statements<-events<-coverage<-obligations<-payments<-list()
 for(b in case$bookings){app<-rj_one(case$applications,'application_id',b$application_id);aid<-b$facility_id;D<-b$first_draw_at;accounts[[length(accounts)+1]]<-list(original_balance=1000,account_id=aid,customer_id=app$customer_id,product_id=product,opened_at=D,known_at=D,currency='EUR');statements[[length(statements)+1]]<-list(statement_id=paste0('statement-',aid),account_id=aid,observed_at=D,known_at=D,balance=1000,credit_limit=1000,dpd=0,past_due_amount=0,currency='EUR');coverage[[length(coverage)+1]]<-list(account_id=aid,observed_through=if(D=='2024-12-31')'2025-01-31'else cutoff,known_at=cutoff)
 due<-as.character(as.Date(D)+10);amount<-rj_payment(case$terms)[1];obligations[[length(obligations)+1]]<-list(obligation_id=paste0('due-',aid),account_id=aid,due_at=due,known_at=D,amount=amount,currency='EUR');if(endsWith(aid,'SURVIVOR')&&amount>0)payments[[length(payments)+1]]<-list(kind='payment',payment_id=paste0('paid-',aid),account_id=aid,paid_at=due,known_at=due,amount=amount,currency='EUR')}
 for(e in case$defaults)events[[length(events)+1]]<-list(event_id=e$event_id,account_id=e$facility_id,event_type='DEFAULT',occurred_at=e$default_at,known_at=e$known_at)
 for(e in case$exits)events[[length(events)+1]]<-list(event_id=e$event_id,account_id=e$facility_id,event_type='CLOSED',occurred_at=e$exit_at,known_at=e$known_at)
 panel<-list();for(D in c('2024-12-31','2025-01-31')){aa<-rj_get(accounts,'opened_at',D);ids<-rj_vec(aa,'account_id');panel<-c(panel,build_account_month_panel(aa,Filter(function(s)s$account_id%in%ids,statements),Filter(function(e)e$account_id%in%ids,events),observation_dates=D)$value$accounts)}
 labels<-build_behavioral_targets(panel,events,horizon_months=1,target_event='DEFAULT',competing_events='CLOSED',exit_treatment='competing',evaluation_cutoff=cutoff,coverage=coverage)$value;risk<-lapply(panel,function(s)predict_behavioral_risk(s,model,target)$value)
 memberships<-lapply(case$applications,function(a)list(customer_id=a$customer_id,household_id=paste0('household-',a$application_id),role='test'))
 source_records<-lapply(seq_along(case$applications),function(i){a<-case$applications[[i]];h<-case$households[[i]];row<-origin$applications[[i]];list(source_id=paste0('feature-',a$application_id),prediction_key=paste0('application:',a$application_id),source_hash=rj_fp(row$snapshot),kind='DOCUMENT',observed_at=h$source_date,available_at=h$source_date)})
 source_records<-c(source_records,lapply(statements,function(s)list(source_id=s$statement_id,prediction_key=paste0('account:',s$account_id,'@',s$observed_at),source_hash=rj_fp(s),kind='STATEMENT',observed_at=s$observed_at,available_at=s$known_at)))
 profile<-list(profile_id=paste0(product,'-retail-target'),version='1',reference='Observed first default before closure; no household contagion',known_at='2024-01-01',default_definition='DECLARED_FIRST_DEFAULT',default_group_rule='facility-only-no-household-contagion',default_unit='facility',first_default=TRUE,exit_treatment='competing',default_event='DEFAULT',chargeoff_event='CHARGEOFF',cure_event='CURED',competing_events=list('CLOSED'),risk_set_by_product=setNames(list(list(active_states=list('ACTIVE','CURED'),include_zero_balance=TRUE)),product),split_isolation_keys=list('customer_id','household_id'),application_horizon_days=30,behavioral_horizon_months=1)
 design<-list(model_id=model$model_id,model_version='1',parameter_version='1',data_fingerprint=rj_fp(case),population_id=paste0(product,'-through-door'),split_id='journey-independent-holdout',prediction_origin='HOLDOUT',evaluation_cutoff=cutoff,target=target)
 args<-list(application_targets=origin$targets,account_panel=panel,behavioral_targets=labels,target_profile=profile,split_memberships=memberships,source_lineage=source_records,design=design)
 payment_history<-list();state_profile<-list(schema_version='1.0',profile_id='declared-retail-delinquency',version='1',materiality=list(absolute=1,relative=0,logic='and'),immaterial_state='CURRENT',buckets=list(list(state='CURRENT',lower=0,upper=1),list(state='ARREARS',lower=1,upper=NULL)),event_priority=list(list(event='utp',state='DEFAULT',at_risk=FALSE,absorbing=TRUE)))
 for(account in accounts){if(account$opened_at!='2024-12-31')next;aid<-account$account_id;obs<-rj_get(obligations,'account_id',aid);pays<-rj_get(payments,'account_id',aid);due<-compute_days_past_due(obs,pays,as_of='2025-01-15',known_at='2025-01-15',currency='EUR')$value;state<-assign_delinquency_state(due$dpd,due$past_due_amount,1000,list(utp=FALSE),state_profile)$value;history<-build_payment_history_features(obs,pays,list(status='COMPLETE',known_at='2025-01-15',observed_from='2024-12-31',complete_through='2025-01-15'),account_id=aid,as_of='2025-01-15',information_cutoff='2025-01-15',lookback_days=15,allocation_policy='fifo',currency='EUR',grace_days=0)$value;payment_history[[length(payment_history)+1]]<-list(account_id=aid,dpd=due,state=state,features=history)}
 vintage<-build_vintage_performance(accounts,panel,events,months_on_book=c(0,1),evaluation_cutoff=cutoff,coverage=coverage,default_event='DEFAULT',delinquency_states=character(),exit_events='CLOSED')$value
 list(payment_history=payment_history,vintage=vintage,training_panel=trpanel,training_targets=trlabels,model=model,accounts=accounts,statements=statements,events=events,coverage=coverage,obligations=obligations,payments=payments,panel=panel,targets=labels,risk=risk,validation_inputs=args,validation=do.call(validate_retail_cohort,args)$value)
}
rj_policy_audit<-function(product,case,origin,target,cutoff){
 target$performance_origin<-NULL;candidate<-list(candidate_id='historical',policy=origin$policy,offer_rule_reference='frozen-product-terms-v1');cases<-inputs<-outcomes<-historical<-list()
 for(i in seq_along(origin$applications)){
  row<-origin$applications[[i]];d<-case$decisions[[i]];key<-row$application$application_id;D<-d$decided_at;label<-row$label;funded<-label$funded;bb<-rj_get(case$bookings,'application_id',key);b<-if(length(bb))bb[[1]]else NULL;observed<-funded&&label$label_observed&&label$mature;pd<-row$risk$pd
  offer<-list(offer_id=key,version='1',known_at=D,currency='EUR',target=target,risk_conditioning='CONDITIONAL_ON_THIS_ACCEPTED_OFFER',assumption_reference='Explicit illustrative uptake0.5 and LGD0.4; not estimated causal effects of price or limit',support_status='SUPPORTED',takeup_probability=.5,conditional_booked_expected_loss=pd*400,conditional_booked_npv=20-pd*400,ead=1000,offer_cost=1,contract_terms=list(limit=1000,annual_rate=0,tenor_days=row$application$requested_terms$term_months*30,currency='EUR',product_terms=case$terms))
  cases[[i]]<-list(case_id=key,decision_date=D,weight=1,split_id='journey-independent-holdout',prediction_reference='product-specific-prior-model-and-calibration',excluded_from_model_training=TRUE,excluded_from_calibration=TRUE)
  inputs[[i]]<-c(list(candidate_id='historical',case_id=key),row$decision_inputs,list(offer=offer,nonapproval_costs=list(REFER=1,DECLINE=0,BLOCKED=0)))
  end<-if(funded)as.character(as.Date(b$first_draw_at)+30)else NULL;ee<-rj_get(case$realized_economics,'application_id',key);economics<-if(length(ee))ee[[1]]else NULL;if(observed&&(is.null(economics)||!economics$complete||economics$known_at>cutoff))stop('Complete actual economic ledger required')
  outcomes[[i]]<-list(case_id=key,funded=funded,complete=observed,booked_offer_hash=if(funded)rj_fp(offer)else NULL,funded_at=if(funded)b$first_draw_at else NULL,funding_known_at=if(funded)b$first_draw_known_at else NULL,outcome_end=end,known_at=if(observed)'2025-01-31'else NULL,defaulted=if(observed)as.logical(label$target)else NULL,economic_loss=if(observed)economics$principal_funded-economics$principal_cash+economics$collection_cost else NULL,net_profit=if(observed)economics$principal_cash+economics$interest_cash-economics$principal_funded-economics$collection_cost else NULL)
  approved<-d$status=='approved';taken<-'accepted_at'%in%names(d)
  historical[[i]]<-list(prediction_id=key,entity_id=row$application$customer_id,cluster_id=row$application$customer_id,segment=product,case_id=key,weight=1,as_of=D,forecast_known_at=D,horizon_end=as.character(as.Date(D)+30),model_id=paste0(product,'-policy-audit'),model_version='1',parameter_version='1',historical_candidate_id='historical',historical_decision=row$decision,offered=approved,taken_up=taken,offered_limit=if(approved)1000 else NULL,booked_amount=if(funded)1000 else NULL,stages_known_at=if(funded)b$first_draw_known_at else D,application_cost=1,cost_known_at=D,cost_complete=TRUE)
 }
 profile<-list(profile_id=paste0(product,'-policy-evaluation'),version='1',known_at='2024-01-01',currency='EUR',registered_at='2024-01-01',outcome_access_date=cutoff,evaluation_role='TEST',prediction_design='HELD_OUT',split_id='journey-independent-holdout',data_fingerprint=rj_fp(case),target=target,candidate_hashes=list(historical=rj_fp(candidate)),objective='expected_npv_per_application',constraints=list(),tie_break='candidate_id',tolerance=1e-12,loss_bounds=list(0,1000),profit_bounds=list(-1000,100))
 grid_inputs<-list(policy_candidates=list(candidate),cases=cases,candidate_inputs=inputs,observed_outcomes=outcomes,evaluation_profile=profile,evaluation_cutoff=cutoff);grid<-do.call(evaluate_decision_grid,grid_inputs)$value
 design<-list(model_id=paste0(product,'-policy-audit'),model_version='1',parameter_version='1',data_fingerprint=profile$data_fingerprint,population_id=paste0(product,'-through-door'),split_id=profile$split_id,prediction_origin='HOLDOUT',evaluation_cutoff=cutoff,currency='EUR',target=target)
 args<-list(evaluated_grid=grid,grid_inputs=grid_inputs,historical_cases=historical,design=design,reference_candidate_id='historical');list(inputs=args,result=do.call(decision_policy_backtest,args)$value)
}
rj_affordability_audit<-function(product,case,origin,cutoff){
 cases<-evidence<-allocations<-payments<-list()
 for(i in seq_along(origin$applications)){
  row<-origin$applications[[i]];h<-case$households[[i]];app<-row$application;key<-app$application_id;b<-row$capacity$baseline;scenario<-row$capacity$scenario;D<-app$application_at;hh<-h$household_id;bindings<-setNames(list(),character())
  for(kind in c('incomes','expenses','contracts','collateral'))for(item in b[[kind]]){eid<-item$economic_id;terms<-item;terms$economic_id<-NULL;proof<-list(evidence_id=paste0('proof-',eid),economic_id=eid,kind=kind,reference=paste0('verified-source-',key),known_at=h$source_date,observed_at=h$source_date,verified=TRUE,terms=terms);if(kind=='incomes')proof$source_basis<-'net';evidence[[length(evidence)+1]]<-proof;bindings[[eid]]<-proof$evidence_id;allocations[[length(allocations)+1]]<-list(allocation_id=paste0('allocation-',eid),economic_id=eid,household_id=hh,as_of=D,known_at=h$source_date,share=1,mode=if(kind=='contracts')'FULL_RECOURSE'else'PROPORTIONAL')}
  end<-scenario$periods[[1]]$date;ids<-lapply(b[c('incomes','expenses','contracts','collateral')],function(group)as.list(rj_vec(group,'economic_id')))
  cases[[i]]<-list(prediction_id=key,entity_id=app$customer_id,cluster_id=hh,segment=product,as_of=D,forecast_known_at=D,horizon_end=end,model_id=paste0(product,'-budget'),model_version='1',parameter_version='1',household_id=hh,baseline=b,scenario=scenario,assessment=row$capacity$stress,evidence_bindings=bindings,expected_economic_ids=ids,scenario_known_at=D,profile_known_at='2024-01-01',profile_version='1')
  aid<-row$label$facility_id;if(!is.null(aid)&&end<=cutoff){ledger<-origin$performing;dues<-sum(vapply(Filter(function(v)v$account_id==aid&&v$due_at<=end,ledger$obligations),function(v)v$amount,numeric(1)));paid<-sum(vapply(Filter(function(v)v$account_id==aid&&v$paid_at<=end,ledger$payments),function(v)v$amount,numeric(1)));payments[[length(payments)+1]]<-list(prediction_id=key,period_date=end,known_at=cutoff,observed_through=end,complete=TRUE,currency='EUR',scheduled_payment=dues,paid_amount=paid)}
 }
 design<-list(model_id=paste0(product,'-budget'),model_version='1',parameter_version='1',data_fingerprint=rj_fp(case),population_id=paste0(product,'-through-door'),split_id='journey-independent-holdout',prediction_origin='HOLDOUT',evaluation_cutoff=cutoff,currency='EUR',target=list(event='default',horizon=1,time_unit='months',probability_measure='PHYSICAL',conditioning='household_budget'))
 args<-list(cases=cases,economic_evidence=evidence,allocations=allocations,design=design,payment_outcomes=payments);list(inputs=args,result=do.call(affordability_stress_backtest,args)$value)
}
rj_monitor<-function(product,case,origin,target,cutoff){
 mt<-list(event='default',probability_measure='PHYSICAL',default_definition='DECLARED_FIRST_DEFAULT',unit='facility',horizon_days=30,default_grade='D');forecasts<-events<-coverage<-list()
 for(b in case$bookings){row<-Filter(function(r)r$application$application_id==b$application_id,origin$applications)[[1]];forecasts[[length(forecasts)+1]]<-list(forecast_id=paste0('forecast-',b$facility_id),case_id=b$application_id,entity_id=b$facility_id,cluster_id=row$application$customer_id,cohort=substr(b$first_draw_at,1,7),segment=product,model_id=origin$fitted$model$model_id,model_version='1',forecast_at=b$first_draw_at,known_at=b$first_draw_at,original_prediction_at=row$application$application_at,pd=row$risk$pd,target=mt,prediction_origin='HOLDOUT');coverage[[length(coverage)+1]]<-list(entity_id=b$facility_id,complete_through=b$followup_end,known_at=b$outcome_available_at)}
 for(e in case$defaults)events[[length(events)+1]]<-list(event_id=e$event_id,entity_id=e$facility_id,event='default',event_at=e$default_at,known_at=e$known_at,default_definition='DECLARED_FIRST_DEFAULT')
 for(e in case$exits)events[[length(events)+1]]<-list(event_id=e$event_id,entity_id=e$facility_id,event='exit',event_at=e$exit_at,known_at=e$known_at,default_definition='DECLARED_FIRST_DEFAULT')
 cohort<-build_monitoring_cohorts(forecasts,events,coverage,target_contract=mt,evaluation_cutoff=cutoff)$value;monitor<-monitor_rating_cohort(cohort,group_by='segment',reference_window=list(start='2024-12-31',end='2024-12-31'),minimum_count=30,uncertainty='none')$value
 log<-dependencies<-list()
 for(i in seq_along(origin$applications)){
  row<-origin$applications[[i]];d<-case$decisions[[i]];key<-row$application$application_id;dependencies[[i]]<-list(assessment_id=row$assessment$assessment_id,dependency_type='application',dependency_id=key)
  phases<-list(list('APPLICATION',row$application$application_at,list(snapshot=row$snapshot$snapshot_hash)),list('DECISION',d$decided_at,list(decision_hash=row$decision$sha256)));bb<-rj_get(case$bookings,'application_id',key)
  if(length(bb)){b<-bb[[1]];phases<-c(phases,list(list('FUNDING',b$first_draw_at,list(facility_id=b$facility_id)),list('MONITORING',cutoff,list(facility_id=b$facility_id,cohort_hash=cohort$cohort_hash))))}
  for(ph in phases){event<-list(event_id=paste0(key,'-',ph[[1]]),idempotency_key=paste0(key,'-',ph[[1]]),occurred_at=ph[[2]],known_at=ph[[2]],sequence=length(log),payload=ph[[3]],revision_of=NULL,payload_hash=rj_fp(ph[[3]]),application_id=key);log[[length(log)+1]]<-event}
 }
 log[[length(log)+1]]<-log[[1]]
 execute<-function(){state<-NULL;seen<-character();applied<-list();ordered<-log[order(rj_vec(log,'known_at'),rj_num(log,'sequence'),rj_vec(log,'event_id'))];for(event in ordered){if(event$idempotency_key%in%seen)next;seen<-c(seen,event$idempotency_key);applied[[length(applied)+1]]<-event$event_id;change<-list(event_id=event$event_id,revision='1',occurred_at=event$occurred_at,known_at=event$known_at,dependencies=list(list(type='application',id=event$application_id)),payload=event$payload);state<-apply_assessment_event(state,change,dependencies,cutoff)$value$state};rerated<-rate_subject_batch(origin$requests,origin$registry,paste0(product,'-batch'),cutoff)$value;list(applied=applied,state=list(dependency_state=state,ratings=rerated$rows))}
 first<-execute();again<-execute();values<-list(origin$fitted$model,origin$fitted$calibrator,origin$policy,case$features);kinds<-c('MODEL','CALIBRATION','POLICY','SOURCE');dates<-c('2018-02-03','2020-02-03','2024-01-01','2025-01-28');snapshots<-lapply(seq_along(kinds),function(i)list(snapshot_id=kinds[i],kind=kinds[i],content_hash=rj_fp(values[[i]]),known_at=dates[i],effective_from=dates[i],effective_until=NULL));hashes<-setNames(lapply(snapshots,function(s)s$content_hash),kinds)
 base<-list(checkpoint_id='final',as_of=cutoff,known_at=cutoff,event_log_hash=rj_fp(log),snapshot_hashes=hashes);original<-c(base,list(applied_event_ids=first$applied,state=first$state));replayed<-c(base,list(applied_event_ids=again$applied,state=again$state,mode='REPLAY'))
 contract<-list(contract_id=paste0(product,'-actual-execution-replay'),version='1',reference='Independent rerating and public dependency-event execution on original frozen inputs',ordering='KNOWN_AT_SEQUENCE_EVENT_ID',idempotency='FIRST_IDENTICAL_DELIVERY',corrections='APPEND_REVISION',required_checkpoint_ids=list('final'),absolute_tolerance=1e-12,relative_tolerance=0)
 args<-list(event_log=log,original_checkpoints=list(original),replayed_checkpoints=list(replayed),snapshot_manifest=snapshots,replay_contract=contract);list(cohort=cohort,monitor=monitor,replay_inputs=args,replay_validation=do.call(replay_consistency,args)$value)
}
run_retail_application_journey<-function(data=NULL,verify_reference=TRUE,product_ids=NULL,applications_path=NULL,releases_path=NULL,return_artifacts=FALSE){
 if(is.null(data))data<-jsonlite::read_json(rj_resource('retail_application_journey.json'),simplifyVector=FALSE)
 sources<-rj_sources(data,applications_path,releases_path);out<-list()
 for(product in names(data$products)){if(!is.null(product_ids)&&!product%in%product_ids)next;case<-data$products[[product]];o<-rj_origination(product,case,data$target,sources);o$performing<-rj_performing(product,case,o,data$evaluation_cutoff);o$policy_validation<-rj_policy_audit(product,case,o,data$target,data$evaluation_cutoff);o$affordability_validation<-rj_affordability_audit(product,case,o,data$evaluation_cutoff);o$monitoring<-rj_monitor(product,case,o,data$target,data$evaluation_cutoff);o$pools<-rj_pools(product,case,o,data$target);out[[product]]<-o}
 result<-list(data_origin=data$data_origin,journey_id=data$journey_id,sources=sources,products=out);if(verify_reference)rj_verify(result);if(return_artifacts)result else rj_presentation(result)
}
rj_verify<-function(result){for(p in result$products){stopifnot(identical(lapply(p$targets,function(r)r$target),list(0L,1L,NULL,NULL,NULL))||identical(lapply(p$targets,function(r)r$target),list(0,1,NULL,NULL,NULL)));stopifnot(identical(vapply(p$applications,function(r)r$decision$action,character(1)),c('APPROVE','APPROVE','DECLINE','APPROVE','APPROVE')),p$performing$validation$decision$status=='PASS',length(p$policy_validation$result$violation_counts)==0,length(p$affordability_validation$result$violation_counts)==0,p$monitoring$replay_validation$decision$status=='PASS');metrics<-p$monitoring$monitor[[1]]$metrics;cells<-unlist(p$fitted$independent_cell_mle);stopifnot(metrics$n==2,abs(metrics$brier-(cells[1]^2+(1-cells[2])^2)/2)<1e-8,p$policy_validation$result$metrics$factual$observed_mean_loss==200)};invisible(TRUE)}
rj_presentation<-function(result){
 products<-list()
 for(name in names(result$products)){
  p<-result$products[[name]];records<-lapply(p$applications,function(row){a<-row$application;l<-row$label;list(application_id=a$application_id,customer_id=a$customer_id,facility_id=l$facility_id,application_at=a$application_at,model_id=row$risk$model_id,model_version=row$risk$model_version,policy_id=p$policy$specification$policy_id,policy_version='1',pd=round(row$risk$pd,8),action=row$decision$action,budget_minimum=round(row$capacity$residual$minimum,2),bureau_state=row$bureau$file_state,funded=l$funded,mature=l$mature,observed=l$label_observed,target=l$target,route_profile=row$route$profile_id)})
  m<-p$monitoring$monitor[[1]];f<-p$policy_validation$result$metrics$factual
  products[[name]]<-list(pool_assignments=unlist(lapply(p$pools$assignments,function(a)lapply(a$assignments,function(r)list(observation_id=r$observation_id,pool_id=r$pool_id))),recursive=FALSE),target=p$fitted$model$target,application_population=p$fitted$model$application_contract$population_ids,calibration_parameter_version=p$fitted$calibrator$parameter_version,applications=records,prior_model=list(training_known_at=p$fitted$model$training$known_at,calibration_known_at=p$fitted$calibrator$metadata$calibration$known_at,cell_mle=p$fitted$independent_cell_mle,fitted_cell_pd=as.list(round(unlist(p$fitted$fit_predictions),8))),account_targets=p$performing$targets,payment_history=lapply(p$performing$payment_history,function(r)list(account_id=r$account_id,dpd=r$dpd$dpd,past_due_amount=r$dpd$past_due_amount,state=r$state$state)),retail_cohort_status=p$performing$validation$decision$status,policy_factual=f,policy_violations=p$policy_validation$result$violation_counts,affordability_status=p$affordability_validation$result$decision$status,payment_bias=p$affordability_validation$result$metrics$factual_scheduled_minus_paid$bias,monitoring=list(status=m$status,n=m$metrics$n,observed_rate=m$metrics$observed_rate,mean_pd=round(m$metrics$mean_pd,8),brier=round(m$metrics$brier,8),excluded_count=m$excluded_count),replay_status=p$monitoring$replay_validation$decision$status,duplicate_deliveries=p$monitoring$replay_validation$metrics$duplicate_identical_deliveries,joint_application=p$joint_application)
 }
 list(data_origin=result$data_origin,journey_id=result$journey_id,reporting=list(probability_decimal_places=8,currency_decimal_places=2,raw_artifacts_available=TRUE,raw_artifact_argument='return_artifacts=True',model_parameters_rounded=FALSE),source_archives=result$sources$archive_hashes,source_validation=lapply(result$sources$audits,function(r)list(cutoff=r$cutoff,status=r$result$decision$status,node_totals=r$result$node_totals)),products=products)
}
rj_pools<-function(product,case,origin,target){
 model<-origin$fitted$model;strata<-list(product=product,borrower_type='person',facility_type=case$terms$kind,delinquency_state='not_defaulted');T<-target;T$conditioning<-'not_defaulted_at_index';T$performance_origin<-NULL;T$default_unit<-'facility';T$default_definition<-'DECLARED_FIRST_DEFAULT';T$currency<-'EUR'
 rows<-lapply(case$training,function(r){score<-predict_pd(model,matrix(r$driver,ncol=1),feature_order='driver',expected_target=target)$value[[1]];c(list(observation_id=r$application_id,index_date=r$first_draw_at,feature_observed_at=r$feature_observed_at,feature_known_at=r$feature_known_at,score=score),strata,list(default_unit_id=r$facility_id,role='TRAIN',label_window_end=r$outcome_end,label_known_at=r$outcome_known_at,defaulted=as.logical(r$outcome),default_date=r$default_at,lgd_status=if(r$outcome)'OPEN'else'NOT_DEFAULTED',lgd=NULL,ead=NULL,lgd_known_at=NULL,ead_known_at=NULL))})
 cut<-mean(unlist(origin$fitted$independent_cell_mle));spec<-list(spec_id=paste0(product,'-application-pools'),version='1',known_at='2017-01-01',stratum_fields=as.list(names(strata)),score_field='score',segments=list(list(segment_id=product,values=strata,cutpoints=list(cut),score_min=0,score_max=1,monotonicity=list(pd='increasing',lgd='none',ead='none'))),minimum_cases=2,minimum_defaults=0,minimum_lgd_count=0,minimum_ead_count=0,maximum_bin_mean_spread=list(pd=NULL,lgd=NULL,ead=NULL));training<-model$training;training$role<-'TRAIN';fit<-fit_retail_risk_pools(rows,spec,target=T,training=training,model_id=paste0(product,'-pools'),model_version='1')
 assignments<-lapply(origin$applications,function(r){a<-r$application;D<-a$application_at;obs<-c(list(observation_id=a$application_id,index_date=D,feature_observed_at=D,feature_known_at=D,score=r$risk$pd),strata);assign_retail_risk_pool(list(obs),fit,as_of=D,information_cutoff=D,expected_target=T,uncovered_policy='error')$value})
 list(training_inputs=rows,model=fit$model,assignments=assignments)
}
